def font(n,b=False):
 try:return ImageFont.truetype(FB if b else F,n)
 except:return ImageFont.load_default()
def wrap(draw,s,f,m):
 out=[];line=''
 for word in s.split():
  test=(line+' '+word).strip()
  if draw.textbbox((0,0),test,font=f)[2]<=m:line=test
  else:
   if line:out.append(line)
   line=word
 if line:out.append(line)
 return out
def diagram(name,title,boxes,arrows,H=750):
 im=Image.new('RGB',(1500,H),'white');d=ImageDraw.Draw(im);d.text((750,35),title,font=font(31,1),fill='#18343c',anchor='mm')
 for x,y,w,h,label,sub in boxes:
  d.rounded_rectangle((x,y,x+w,y+h),20,fill='#edf6f4',outline='#26776e',width=3); yy=y+18
  for line in wrap(d,label,font(22,1),w-24):d.text((x+w//2,yy),line,font=font(22,1),fill='#18343c',anchor='mt');yy+=28
  yy+=4
  for line in wrap(d,sub,font(16),w-24):d.text((x+w//2,yy),line,font=font(16),fill='#34545a',anchor='mt');yy+=21
 for x1,y1,x2,y2,lab in arrows:
  d.line((x1,y1,x2,y2),fill='#526a72',width=3);a=math.atan2(y2-y1,x2-x1);d.polygon([(x2,y2),(x2-14*math.cos(a-.5),y2-14*math.sin(a-.5)),(x2-14*math.cos(a+.5),y2-14*math.sin(a+.5))],fill='#526a72')
  if lab:d.text(((x1+x2)//2,(y1+y2)//2-14),lab,font=font(15,1),fill='#415860',anchor='mm')
 p=W/(name+'.png');im.save(p);return p
