   cells[j].text=str(v);cells[j].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   if i%2: sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'F1F6F7');cells[j]._tc.get_or_add_tcPr().append(sh)
